using NUnit.Framework;
using UnityEngine;
using LWS.TruckSnake;
public sealed class SnakePathTests {
 [Test]public void ArcLengthSpacesFiftySegmentsWithoutJointDrift(){var p=new SnakePathHistory();p.Reset(Vector3.zero,Quaternion.identity);for(int i=1;i<=4000;i++)p.Append(new Vector3(0,0,i*.5f),Quaternion.identity);for(int i=0;i<50;i++){Assert.That(p.TryBehind(8+i*16,out var sample));Assert.That(sample.position.z,Is.EqualTo(2000-8-i*16).Within(.001));}}
 [Test]public void ThreeDimensionalJumpIsDelayedDownTheTrain(){var p=new SnakePathHistory();p.Reset(Vector3.zero,Quaternion.identity,50);for(int i=1;i<=100;i++){float z=i*.5f;p.Append(new Vector3(0,Mathf.Sin(Mathf.Clamp01((z-10)/30)*Mathf.PI)*10,z),Quaternion.identity);}Assert.That(p.TryBehind(4,out var front));Assert.That(p.TryBehind(24,out var middle));Assert.That(p.TryBehind(48,out var rear));Assert.That(middle.position.y,Is.GreaterThan(front.position.y+2));Assert.That(middle.position.y,Is.GreaterThan(rear.position.y+2));}
 [Test]public void CurvedHistoryInterpolatesActualRoute(){var p=new SnakePathHistory();p.Reset(Vector3.right*20,Quaternion.identity);for(int i=1;i<=180;i++){float a=i*Mathf.Deg2Rad;p.Append(new Vector3(Mathf.Cos(a)*20,0,Mathf.Sin(a)*20),Quaternion.LookRotation(new Vector3(-Mathf.Sin(a),0,Mathf.Cos(a))),0);}Assert.That(p.TryBehind(20,out var s));Assert.That(s.position.magnitude,Is.EqualTo(20).Within(.002));}
 [Test]public void RingWrapRetainsTheNewestCorrectSamples(){var p=new SnakePathHistory(64);p.Reset(Vector3.zero,Quaternion.identity);for(int i=1;i<=200;i++)p.Append(Vector3.forward*i,Quaternion.identity);Assert.That(p.Count,Is.EqualTo(64));Assert.That(p.TryBehind(20,out var s));Assert.That(s.position.z,Is.EqualTo(180));Assert.That(p.TryBehind(70,out _),Is.False);}
 [Test]public void ResetCannotReplayLastRunsTail(){var p=new SnakePathHistory();p.Reset(Vector3.zero,Quaternion.identity,100);p.Append(Vector3.forward*300,Quaternion.identity);p.Reset(Vector3.right*500,Quaternion.identity);Assert.That(p.Count,Is.EqualTo(1));Assert.That(p.TryBehind(1,out _),Is.False);}
 [Test]public void StoppedSamplesDoNotConsumeHistory(){var p=new SnakePathHistory(64);p.Reset(Vector3.zero,Quaternion.identity);for(int i=0;i<1000;i++)p.Append(Vector3.zero,Quaternion.identity);Assert.That(p.Count,Is.EqualTo(1));}
 [Test]public void CapacityAndNonFiniteSamplesAreRejected(){Assert.Throws<System.ArgumentOutOfRangeException>(()=>new SnakePathHistory(2));var p=new SnakePathHistory();Assert.Throws<System.ArgumentException>(()=>p.Append(new Vector3(float.NaN,0,0),Quaternion.identity));}
 [Test]public void HistoryPruningPreservesLongTail(){var p=new SnakePathHistory();p.Reset(Vector3.zero,Quaternion.identity);for(int i=1;i<=5000;i++)p.Append(Vector3.forward*i,Quaternion.identity);p.Trim(1200);Assert.That(p.Count,Is.LessThan(1210));Assert.That(p.TryBehind(800,out var s));Assert.That(s.position.z,Is.EqualTo(4200));}
 [Test]public void StandardAndGoldenAwardExactlyOneAndThree(){var r=new SnakeRules();r.Start(2,SnakeMode.Competitive);Assert.That(r.Pickup(0,false));Assert.That(r.Pickup(1,true));Assert.That(r.trailers[0],Is.EqualTo(2));Assert.That(r.trailers[1],Is.EqualTo(4));}
 [Test]public void CrashFreezesThatParticipantsRewards(){var r=new SnakeRules();r.Start(2,SnakeMode.Competitive);r.Pickup(0,true);r.Crash(0);Assert.That(r.Pickup(0,true),Is.False);r.Step(10,new[]{100f,100f});Assert.That(r.distance[0],Is.Zero);Assert.That(r.distance[1],Is.EqualTo(100));}
 [Test]public void TimedTieSharesVictory(){var r=new SnakeRules();r.Start(4,SnakeMode.Timed,10);r.Step(10,new[]{100f,100f,100f,100f});Assert.That(r.Complete);foreach(bool winner in r.winners)Assert.That(winner);}
 [Test]public void ComboExpiresWithoutChangingLength(){var r=new SnakeRules();r.Start(1,SnakeMode.Endless);r.Pickup(0,false);r.Step(5,null);r.Pickup(0,false);Assert.That(r.combo[0],Is.EqualTo(2));r.Step(13,null);Assert.That(r.combo[0],Is.Zero);Assert.That(r.trailers[0],Is.EqualTo(3));}
 [Test]public void FailureDoesNotEndOtherCompetitors(){var r=new SnakeRules();r.Start(4,SnakeMode.Competitive);r.Crash(0);r.Crash(1);r.Crash(2);Assert.That(r.Complete,Is.False);r.Crash(3);Assert.That(r.Complete);}
 [Test]public void GenuineJumpHasBoundedBonus(){var r=new SnakeRules();r.Start(1,SnakeMode.Endless);Assert.That(r.LandJump(0,.2f,30),Is.False);Assert.That(r.LandJump(0,2,10000));Assert.That(r.score[0],Is.EqualTo(300));}
 [Test]public void TailPenaltyNeverCreatesNegativeLength(){var r=new SnakeRules();r.Start(1,SnakeMode.Endless);r.Pickup(0,true);Assert.That(r.LoseTail(0,5),Is.False);Assert.That(r.LoseTail(0,2));Assert.That(r.trailers[0],Is.EqualTo(2));}
 [Test]public void ActualPickupAccessGraphHasUniqueIdentifiersAndEndsAtPickup(){var type=System.Type.GetType("LWS.TruckSnake.Editor.SnakeNavigationFixtures, Assembly-CSharp-Editor",true);Assert.DoesNotThrow(()=>type.GetMethod("TerminalEdgeRetainsUniqueSchemaAndReachesMidRoadPickup").Invoke(null,null));}
 [Test]public void BridgeAndGroundRoutesRemainDistinct(){var t=System.Type.GetType("LWS.TruckSnake.Editor.SnakeNavigationFixtures, Assembly-CSharp-Editor",true);Assert.DoesNotThrow(()=>t.GetMethod("ElevatedParallelRouteIsNotTheGroundRoad").Invoke(null,null));}
 [Test]public void SolidImpactUsesTheSameContactNormalAndSpeed(){var t=System.Type.GetType("LWS.TruckSnake.Editor.SnakeNavigationFixtures, Assembly-CSharp-Editor",true);Assert.DoesNotThrow(()=>t.GetMethod("FloorVelocityCannotQualifyGentleFrontalScrape").Invoke(null,null));}

 [Test]public void StarterCargoIsNotAnEarnedPickup(){var r=new SnakeRules();r.Start(4,SnakeMode.Timed);for(int i=0;i<4;i++){Assert.That(r.trailers[i],Is.EqualTo(1));Assert.That(r.collected[i],Is.Zero);Assert.That(r.score[i],Is.Zero);Assert.That(r.attached[i],Is.Zero);r.SetAttached(i,1);Assert.That(r.ScoreMultiplier(i),Is.EqualTo(1));}}
 [Test]public void RealAttachedLengthMultipliesDistanceAndSurvival(){var r=new SnakeRules();r.Start(2,SnakeMode.Timed);r.Pickup(0,true);r.Pickup(1,true);r.SetAttached(0,1);r.SetAttached(1,4);int a=r.score[0],b=r.score[1];r.Step(5,new[]{100f,100f});Assert.That(r.score[0]-a,Is.EqualTo(15));Assert.That(r.score[1]-b,Is.EqualTo(60));}
 [Test]public void PendingCargoCannotInflateAnyScoreReward(){var r=new SnakeRules();r.Start(2,SnakeMode.Timed);r.SetAttached(0,1);r.SetAttached(1,1);r.Pickup(0,true);r.Pickup(1,true);r.SetAttached(1,4);int a=r.score[0],b=r.score[1];r.Pickup(0,false);r.Pickup(1,false);Assert.That(r.score[1]-b,Is.EqualTo((r.score[0]-a)*4));a=r.score[0];b=r.score[1];r.LandJump(0,2,20);r.LandJump(1,2,20);Assert.That(r.score[1]-b,Is.EqualTo((r.score[0]-a)*4));Assert.Throws<System.ArgumentOutOfRangeException>(()=>r.SetAttached(0,99));}
 [Test]public void TailLossReducesFutureEarningsAndRematchRestoresOne(){var r=new SnakeRules();r.Start(1,SnakeMode.Endless);r.Pickup(0,true);r.SetAttached(0,4);Assert.That(r.LoseTail(0,2));Assert.That(r.ScoreMultiplier(0),Is.EqualTo(2));r.Start(1,SnakeMode.Endless);Assert.That(r.trailers[0],Is.EqualTo(1));Assert.That(r.attached[0],Is.Zero);Assert.That(r.score[0],Is.Zero);}
}

